\title{Estimating the Secret Fan Vote on \textit{Dancing with the Stars}:\\
A Constrained Inversion of 34 Seasons of Judge Scores and Eliminations}

\author{Team \#~~~~ \\
\small Based on the 2026 MCM Problem C data set}
\date{\today}

